widget.solution:
from fractions import Fraction
from functools import lru_cache


@lru_cache(maxsize=None)
def card_game_value(r, b):
    if r == 0:
        return Fraction(0)
    if b == 0:
        return Fraction(r)
    go = (Fraction(r, r + b) * (1 + card_game_value(r - 1, b))
          + Fraction(b, r + b) * (-1 + card_game_value(r, b - 1)))
    return max(Fraction(0), go)
